insert into agent_findings (id, project_id, agent_type, title, statement, severity, confidence, evidence, status) values 
  ('00000000-0000-0000-0000-000000001001', '00000000-0000-0000-0000-000000000100', 'CostMonitorAgent', 'High-Pressure Piping Spool Unit Rate 14% Above Baseline Budget', 'Actual spool fabrication invoices from PT McDermott reflect higher unit cost ($969/meter) vs approved budget line ($850/meter).', 'HIGH', 0.93, '{"wbs":"3.2","budgetUnitPrice":850,"invoiceUnitPrice":969,"vendor":"PT McDermott","invoiceRef":"INV-2026-042"}'::jsonb, 'NEW'),
  ('00000000-0000-0000-0000-000000001002', '00000000-0000-0000-0000-000000000100', 'BudgetVarianceAgent', 'Cumulative Cost Performance Index (CPI) Degraded to 0.95 in Period 06', 'Period actual cost ($1.25M) outpaces physical earned value ($1.19M), driven by heavy foundation dewatering and trenching overtime.', 'MEDIUM', 0.91, '{"cpi":0.952,"threshold":0.97,"driver":"Civil Trenching Dewatering Overruns","spi":0.850}'::jsonb, 'NEW'),
  ('00000000-0000-0000-0000-000000001003', '00000000-0000-0000-0000-000000000100', 'CommitmentGapAgent', 'Uncommitted Buffer Gap in 150kV High Voltage Substation Package', 'Substation package WBS 4.1 has $220k in uncommitted budget lines with only 8 weeks remaining before scheduled civil turnover.', 'MEDIUM', 0.88, '{"wbs":"4.1","budget":450000,"committed":230000,"uncommitted":220000,"daysToTurnover":56}'::jsonb, 'NEW'),
  ('00000000-0000-0000-0000-000000001004', '00000000-0000-0000-0000-000000000100', 'PeriodStalenessAgent', 'Goods Receipt Note GRN-2026-018 Unposted for 24 Days', 'Piping Spool batch delivery note remains in draft accrual state without formal vendor invoice matching past the 14-day SLA.', 'LOW', 0.95, '{"reference":"GRN-2026-018","daysOpen":24,"thresholdDays":14,"amount":85000}'::jsonb, 'NEW'),
  ('00000000-0000-0000-0000-000000001005', '00000000-0000-0000-0000-000000000100', 'AnomalyDetectorAgent', 'Statistical Outlier Surcharge on Heavy Lifting Crane Invoice INV-2026-051', 'Mobilization invoice from Mammoet exhibits a z-score of 3.14 compared to baseline crane hire distribution.', 'HIGH', 0.89, '{"zScore":3.14,"amount":70000,"historicalMean":42000,"vendor":"Mammoet","sourceRef":"INV-2026-051"}'::jsonb, 'NEW');
